const inputs = [
  '2020-08-06T03:48:10.258Z',
  '2020-08-06T03:48:10Z',
  '2020-08-06T03:48:10.001Z',
  '2020-08-06T03:48:10.999Z',
  '2014-06-01T12:00:00.500Z',
  '2014-12-01T12:00:00.123Z',
  '2012-03-11T06:59:59.700Z',
  '2012-11-04T05:59:59.400Z'
]

it('offset matches moment for fractional and whole seconds', () => {
  zones.forEach((z) => {
    inputs.forEach((i) => {
      const d = dayjs(i).tz(z)
      const m = moment(i).tz(z)
      expect([z, i, d.format('Z')]).toEqual([z, i, m.format('Z')])
      expect([z, i, d.format()]).toEqual([z, i, m.format()])
      expect([z, i, d.format('SSS')]).toEqual([z, i, m.format('SSS')])
      expect([z, i, d.valueOf()]).toEqual([z, i, m.valueOf()])
      expect([z, i, d.utcOffset()]).toEqual([z, i, m.utcOffset()])
    })
  })
})

it('explicit bug report example', () => {
  expect(dayjs('2020-08-06T03:48:10.258Z').tz('Asia/Tokyo').format('Z')).toBe('+09:00')
  expect(dayjs('2020-08-06T03:48:10.258Z').tz('Asia/Tokyo').format()).toBe('2020-08-06T12:48:10+09:00')
